import{t as e}from"./arrow-left-DdpsRgH7.js";import{t}from"./shield-check-oGf5Ysaa.js";import{I as n,N as r,s as i}from"./index-DXvnp12t.js";var a=n(),o=[{title:`1. Controladora dos dados e abrangência`,body:[`A S.O.S Cursos, doravante denominada simplesmente "S.O.S Cursos" ou "nós", atua como controladora dos dados pessoais tratados por meio deste site, nos termos do art. 5º, VI, e art. 37 da Lei nº 13.709/2018 (LGPD).`,`Esta Política de Privacidade se aplica a todos os visitantes, alunos, responsáveis legais de alunos menores e demais titulares de dados que interajam com o nosso site ou com os nossos canais de atendimento (WhatsApp e e-mail).`]},{title:`2. Princípios do tratamento (art. 6º da LGPD)`,body:[`Todo tratamento de dados pessoais realizado por nós observa os princípios da finalidade, adequação, necessidade, livre acesso, qualidade dos dados, transparência, segurança, prevenção, não discriminação e responsabilização, conforme o art. 6º da LGPD.`,`Isso significa que: coletamos apenas o mínimo necessário; usamos seus dados somente para as finalidades informadas nesta política; e adotamos medidas para garantir segurança, correção e transparência em todas as etapas do tratamento.`]},{title:`3. Quais dados coletamos e como`,body:[`Coletamos apenas os dados estritamente necessários ao funcionamento dos nossos serviços:`,`– Informações fornecidas por você: nome, telefone (WhatsApp), e-mail e o conteúdo das mensagens enviadas espontaneamente pelos nossos canais de atendimento;`,`– Dados de navegação: endereço IP, data e hora de acesso, páginas visitadas, tipo de dispositivo e navegador, coletados de forma automatizada para fins estatísticos, de segurança e de prevenção a fraudes;`,`– Dados de pagamento: o processamento financeiro (PIX, cartões e boletos) é realizado exclusivamente por instituições de pagamento que atuam como operadoras independentes, com políticas próprias. Não coletamos nem armazenamos dados de cartão de crédito em nossos servidores.`,`Não coletamos dados sensíveis (art. 5º, II, da LGPD), como origem racial, convicção religiosa, opinião política ou dados de saúde, salvo se você os fornecer voluntariamente em mensagens de atendimento.`]},{title:`4. Finalidades e bases legais (art. 7º da LGPD)`,body:[`Tratamos seus dados pessoais para as seguintes finalidades, com as respectivas bases legais:`,`– Atendimento, matrícula, emissão de certificado e suporte ao aluno: execução de contrato e de procedimentos preliminares (art. 7º, V);`,`– Comunicação sobre cursos em que você demonstrou interesse: legítimo interesse (art. 7º, IX) ou consentimento (art. 7º, I);`,`– Segurança, prevenção a fraudes e proteção do nosso conteúdo: legítimo interesse (art. 7º, IX);`,`– Cumprimento de obrigações legais, fiscais e regulatórias: cumprimento de obrigação legal (art. 7º, II);`,`O consentimento, quando exigido, é livre, informado e inequívoco, e pode ser revogado a qualquer momento, sem prejuízo da legalidade do tratamento realizado antes da revogação.`]},{title:`5. Compartilhamento e proteção dos nossos cursos`,body:[`Não vendemos, alugamos, cedemos ou compartilhamos seus dados pessoais com terceiros para fins comerciais. O acesso às aulas, aos materiais e aos certificados é pessoal e intransferível, sendo vedado ao aluno compartilhar suas credenciais de acesso.`,`Todo o conteúdo dos cursos, materiais de apoio, marcas, logotipos e identidade visual são de propriedade da S.O.S Cursos e de seus parceiros, protegidos pela Lei nº 9.610/98 (Direitos Autorais) e pela Lei nº 9.279/96 (Propriedade Industrial). É vedada a cópia, reprodução, distribuição, compartilhamento ou revenda, total ou parcial, sem autorização expressa e por escrito.`,`Para a defesa dos direitos da S.O.S Cursos e de seus parceiros, poderemos registrar informações de acesso (IP, data, hora e dispositivo) e utilizá-las em procedimentos administrativos ou judiciais quando houver indício de fraude, violação de direitos autorais, uso indevido dos nossos produtos ou descumprimento das condições de uso.`]},{title:`6. Transferência internacional de dados (art. 33 da LGPD)`,body:[`Eventualmente, podemos utilizar serviços de terceiros (como plataformas de hospedagem, envio de e-mails e ferramentas de estatística) que armazenam dados em servidores localizados fora do Brasil. Nesses casos, garantimos que a transferência ocorre em conformidade com o art. 33 da LGPD, adotando cláusulas contratuais adequadas e níveis de proteção compatíveis com a legislação brasileira.`]},{title:`7. Direitos do titular (art. 18 da LGPD)`,body:[`Nos termos do art. 18 da LGPD, você pode solicitar, a qualquer momento e gratuitamente:`,`– confirmação da existência de tratamento de seus dados pessoais;`,`– acesso aos dados tratados;`,`– correção de dados incompletos, inexatos ou desatualizados;`,`– anonimização, bloqueio ou eliminação de dados desnecessários, excessivos ou tratados em desconformidade com a lei;`,`– portabilidade dos dados a outro fornecedor de serviço ou produto;`,`– eliminação dos dados tratados com base no consentimento;`,`– informação sobre as entidades públicas e privadas com as quais compartilhamos seus dados;`,`– informação sobre a possibilidade de não fornecer consentimento e sobre as consequências da negativa;`,`– revogação do consentimento (art. 8º, § 5º).`,`As solicitações devem ser encaminhadas pelo e-mail indicado na seção 11 e serão respondidas no prazo de até 15 (quinze) dias, conforme o art. 18, § 2º, da LGPD. Caso não seja possível atender à solicitação, informaremos os motivos. Você também pode apresentar reclamação à Autoridade Nacional de Proteção de Dados (ANPD).`]},{title:`8. Crianças e adolescentes (art. 14 da LGPD)`,body:[`Os cursos da linha Kids são voltados ao público infantil. A matrícula e o atendimento são realizados exclusivamente com a supervisão e o consentimento específico e destacado dos pais ou responsáveis legais, conforme o art. 14 da LGPD. Os dados de crianças e adolescentes são tratados com redobrado cuidado e utilizados somente para a prestação do serviço contratado.`]},{title:`9. Segurança, retenção e incidentes`,body:[`Adotamos medidas técnicas e organizacionais adequadas, incluindo criptografia em trânsito e controle de acesso, para proteger seus dados contra acessos não autorizados, perda, alteração ou destruição (art. 46 da LGPD).`,`Mantemos seus dados somente pelo tempo necessário às finalidades desta política ou enquanto houver obrigação legal de guarda, inclusive para o exercício regular de direitos em processo judicial, administrativo ou arbitral.`,`Em caso de incidente de segurança que possa acarretar risco ou dano relevante, comunicaremos você e a ANPD, conforme o art. 48 da LGPD.`]},{title:`10. Alterações desta política`,body:[`Esta política pode ser atualizada sempre que necessário, especialmente para refletir mudanças legais ou nos nossos serviços. A versão vigente estará sempre disponível nesta página, com a data de atualização. A continuidade no uso do site após a publicação de alterações implica ciência e concordância com os novos termos.`]}];function s(){return(0,a.jsxs)(`div`,{className:`privacy-page`,children:[(0,a.jsx)(`header`,{className:`privacy-header`,children:(0,a.jsxs)(`a`,{className:`brand`,href:`#topo`,"aria-label":`S.O.S Cursos início`,children:[(0,a.jsx)(`span`,{className:`brand-badge`,children:`SOS`}),(0,a.jsxs)(`span`,{className:`brand-text`,children:[`S.O.S `,(0,a.jsx)(`strong`,{children:`CURSOS`})]})]})}),(0,a.jsx)(`main`,{className:`privacy-main`,children:(0,a.jsxs)(`div`,{className:`container`,children:[(0,a.jsxs)(`a`,{className:`privacy-back`,href:`#topo`,children:[(0,a.jsx)(e,{strokeWidth:2.4}),` Voltar para o site`]}),(0,a.jsx)(`p`,{className:`eyebrow`,children:`Privacidade`}),(0,a.jsxs)(`h1`,{className:`privacy-title`,children:[(0,a.jsx)(t,{strokeWidth:2}),` Política de Privacidade`]}),(0,a.jsx)(`p`,{className:`privacy-updated`,children:`Última atualização: 18 de agosto de 2026`}),(0,a.jsx)(`p`,{className:`privacy-intro`,children:`Esta Política de Privacidade descreve, de forma clara e transparente, como a S.O.S Cursos coleta, usa, armazena, compartilha e protege os dados pessoais de quem acessa nosso site ou contrata nossos cursos, em conformidade com a Lei nº 13.709/2018 (LGPD), o Marco Civil da Internet (Lei nº 12.965/2014) e demais normas aplicáveis.`}),(0,a.jsx)(`div`,{className:`privacy-sections`,children:o.map(e=>(0,a.jsxs)(`section`,{children:[(0,a.jsx)(`h2`,{children:e.title}),e.body.map(e=>e.startsWith(`–`)?(0,a.jsx)(`p`,{className:`privacy-item`,children:e},e):(0,a.jsx)(`p`,{children:e},e))]},e.title))}),(0,a.jsxs)(`section`,{className:`privacy-contact`,children:[(0,a.jsx)(`h2`,{children:`11. Fale conosco e encarregado de dados`}),(0,a.jsx)(`p`,{children:`Em caso de dúvidas sobre esta política, para exercer seus direitos como titular ou para falar com o nosso Encarregado de Dados (DPO), entre em contato:`}),(0,a.jsxs)(`p`,{children:[(0,a.jsx)(r,{strokeWidth:2}),` `,(0,a.jsx)(`a`,{href:`mailto:${i.email}`,children:i.email})]}),(0,a.jsx)(`p`,{className:`privacy-dpo-note`,children:`Atendimento em até 15 (quinze) dias úteis. Você também pode registrar reclamação junto à Autoridade Nacional de Proteção de Dados (ANPD).`})]})]})}),(0,a.jsx)(`footer`,{className:`privacy-footer`,children:(0,a.jsx)(`div`,{className:`container`,children:(0,a.jsx)(`p`,{children:`© 2026 S.O.S Cursos. Todos os direitos reservados.`})})})]})}export{s as default};